import gzip,csv,glob
for i in [1,5]:
 f=glob.glob(f'studies/data/raw/paper_{i}_*series*')[0]
 rows=[r for r in csv.reader(gzip.open(f,'rt'),delimiter='\t') if r and r[0].startswith('!Sample')]
 if i==1:
  for r in rows:
   if any(x in r[0] for x in ['description','extract','characteristics']):print(r[0],set(r[1:]))
 else:
  for j in range(1,len(rows[0])):
   if any(r[j]=='cell line: MCF-7' for r in rows):
    print([(r[0],r[j]) for r in rows if r[0] in ['!Sample_geo_accession','!Sample_characteristics_ch1']])
